ACT['x2-stgen'] = function(el){ var k = el.getAttribute('data-k'); if(x2AIoff() || !a2Set('studio.on')) return toast(L('The Studio is off — the owner switches it on with a spend cap', 'স্টুডিও বন্ধ — মালিক খরচের সীমাসহ চালু করবেন')); if(!a2Set('studio.cap')) return toast(L('Set a monthly spend cap first', 'আগে মাসের খরচের সীমা দিন')); var x = x2S(); x.studio.unshift({id:'ST-' + (32 + x.studio.length), kind:k, title:L(X2_SK[k][0], X2_SK[k][1]) + ' · ' + a2date(Date.now()), st:'queued', cost:0, at:Date.now()}); x2Done('Generate job queued — you get a notification when it is ready', 'কাজ লাইনে গেল'); };
ACT['x2-stpub'] = function(el){ var j = x2S().studio.filter(function(z){ return z.id === el.getAttribute('data-id'); })[0]; a2Confirm({title:'Publish this?', bn:'পাবলিশ করবেন?', effects:[L('Goes out on the connected channel (mock until connected)', 'যুক্ত চ্যানেলে যাবে (নমুনা)'), L('Logged under your name', 'আপনার নামে লগ হবে')], ok:'Publish', okBn:'পাবলিশ', fn:function(){ j.st = 'published'; x2Done('Published: ' + j.title, 'পাবলিশ হলো'); }}); };
ACT['x2-stno'] = function(el){ var j = x2S().studio.filter(function(z){ return z.id === el.getAttribute('data-id'); })[0]; j.st = 'declined'; x2Done('Declined: ' + j.title, 'বাতিল হলো'); };
ACT['x2-stask'] = function(el){ var j = x2S().studio.filter(function(z){ return z.id === el.getAttribute('data-id'); })[0]; j.st = 'approval'; x2Done('Sent for approval: ' + j.title, 'অনুমোদনে গেল'); };

/* ---------- MKT-07 Market & competitor intelligence ---------- */
a2Page({path:'/admin/marketing/intel', section:'marketing', tab:'intel', en:'Market & competitors', bn:'বাজার আর প্রতিযোগী', perm:'marketing.read', syn:'competitor intelligence price compare market alerts', render:function(p, q, ctx){
  var x = x2S();
  var src = x2Card(Le('Links you follow', 'যে লিংক দেখছেন'), Le('Only links you add are read', 'শুধু আপনার দেওয়া লিংক পড়া হয়'), x.intel.map(function(i){ return '<div class="a2-prow"><span class="a2-tki mute">' + a2i('globe', 16) + '</span><div class="a2-prt"><b>' + esc(i.name) + '</b><span>' + i.items + L(' products matched · ', 'টা মেলানো · ') + esc(i.change) + '</span></div><span class="a2-pru">' + a2ago(i.at) + '</span></div>'; }).join('') + '<div class="x2-scan" style="margin-top:12px"><label class="a2-sr" for="x2inu">Link</label><input id="x2inu" class="a2-inp" type="url" placeholder="https://…">' + x2Btn('x2-inadd', 'Add link', 'লিংক যোগ', {ic:'plus'}) + '</div>');
  var cmp = DB.products.slice(0, 6).map(function(pp, i){ var th = Math.round(pp.price * (0.86 + (i * 7 % 30) / 100) / 10) * 10; return '<tr><td><div class="x2-pc">' + a2Thumb(pp.id) + '<span class="a2-cell"><b>' + esc(pp.name) + '</b></span></div></td><td class="r a2-num">' + a2tk(pp.price) + '</td><td class="r a2-num">' + a2tk(th) + '</td><td class="r">' + (th < pp.price ? x2Pill('warn', Le('they are ', 'তারা ') + a2tk(pp.price - th) + Le(' lower', ' কম')) : x2Pill('ok', Le('you are lower', 'আপনি কম'))) + '</td></tr>'; }).join('');
  return a2Head(ctx, {sub:Le('Compare with the shops you choose, and get told when their prices or ranges change. Proposals only — prices change in the ERP.', 'আপনার বাছাই দোকানের সাথে তুলনা। শুধু প্রস্তাব — দাম বদলায় ERP-তে।')}) + a2Tabs(ctx) + a2Mock(L('comparisons use sample numbers until links are added and the reader is on', 'লিংক না দেওয়া পর্যন্ত নমুনা')) +
    '<div class="a2-row a2-r21"><div class="a2-stack">' + x2Card(Le('Price comparison', 'দামের তুলনা'), Le('Your ERP price vs the lowest matched price', 'আপনার দাম বনাম সবচেয়ে কম মেলানো দাম'), '<div class="a2-tblw" style="box-shadow:none"><table class="a2-tbl"><thead><tr><th>' + Le('Product', 'প্রোডাক্ট') + '</th><th class="r">' + Le('You', 'আপনি') + '</th><th class="r">' + Le('Lowest seen', 'সবচেয়ে কম') + '</th><th class="r">' + Le('Gap', 'পার্থক্য') + '</th></tr></thead><tbody>' + cmp + '</tbody></table></div>') + '</div><div class="a2-stack">' + src +
    a2SetCard({id:'mkt-intel', en:'Change alerts', bn:'বদলের সতর্কতা', where:'Marketing › Market & competitors', desc:'A note in your notifications when a followed shop changes a price or adds a range.', descBn:'দোকান দাম বদলালে বা নতুন কিছু আনলে জানায়।', key:'intel.alerts'}) + '</div></div>';
}});
ACT['x2-inadd'] = function(){ var i = document.getElementById('x2inu'), v = i ? i.value : ''; if(!/^https?:\/\/\S+\.\S+/.test(v)) return toast(L('Paste a full link starting with https://', 'https:// দিয়ে পুরো লিংক দিন')); var host = v.replace(/^https?:\/\//, '').split('/')[0]; x2S().intel.unshift({id:'IN-' + Date.now().toString().slice(-4), name:host, url:v, items:0, change:L('reading for the first time', 'প্রথমবার পড়া হচ্ছে'), at:Date.now()}); x2Done('Link added: ' + host, 'লিংক যোগ হলো'); };

